Task: Return 0 when energy is below 30, 1 when it is below 70, and 2 otherwise.
Signature: int shield_mode(int energy)

Student code:
```c
int shield_mode(int energy)
{
    int lowerThresholdValue = 30;
    int upperThresholdValue = 60;
    int isEnergyBelowLowerThreshold = 0;
    int isEnergyBelowUpperThreshold = 0;
    int shieldModeResult = 0;

    if (energy < lowerThresholdValue)
    {
        isEnergyBelowLowerThreshold = 1;
    }
    else
    {
        isEnergyBelowLowerThreshold = 0;
    }

    if (energy < upperThresholdValue)
    {
        isEnergyBelowUpperThreshold = 1;
    }
    else
    {
        isEnergyBelowUpperThreshold = 0;
    }

    if (isEnergyBelowLowerThreshold == 1)
    {
        shieldModeResult = 0;
    }
    else
    {
        if (isEnergyBelowUpperThreshold == 1)
        {
            shieldModeResult = 1;
        }
        else
        {
            shieldModeResult = 2;
        }
    }

    return shieldModeResult;
}
```
